2	// 書き込む行のほかは、1 文字も変えない (改行の文字・最後の改行の有無も含む)。
3	// publish は空の資料を作った直後に URL を書き込むので、スライドの部分に書式の誤りがあっても書き込む。
4	// 検査するのは、題名の行と資料の情報の行だけにする。
5	
6	import {
7	  checkPluginVersion,
8	  formatOutlineError,
9	  INFO_LABELS,
10	  parseGoogleSlidesUrl,
11	  scanHeader,
12	} from "./parse.ts";
13	
14	/** 書き込みの結果。誤りがあれば、構成案のテキストは変えずに、誤りの配列を返す。 */
15	export type WriteInfoResult = { ok: true; text: string } | { ok: false; errors: string[] };
16	
17	/**
18	 * Google スライドの URL の行を書き込む。
19	 * 行が無ければ資料の情報の最後に 1 行を足し、あれば、その行だけを置き換える。
20	 */
21	export function writeGoogleSlidesUrl(text: string, url: string): WriteInfoResult {
22	  const ref = parseGoogleSlidesUrl(url);
23	  if (typeof ref === "string") return { ok: false, errors: [ref] };
24	  return writeItem(text, "googleSlides", url);
25	}
26	
27	/**
28	 * slide-deck の版の行を書き込む。
29	 * 行が無ければ資料の情報の最後に 1 行を足し、あれば、その行だけを置き換える。
30	 */
31	export function writePluginVersion(text: string, version: string): WriteInfoResult {
32	  const e = checkPluginVersion(version);
33	  if (e !== null) return { ok: false, errors: [e] };
34	  return writeItem(text, "pluginVersion", version);
35	}
36	
37	function writeItem(
38	  text: string,
39	  field: "googleSlides" | "pluginVersion",
40	  value: string,
41	): WriteInfoResult {
42	  // 改行の文字を行に残して分ける。関数 scanHeader に渡す行 (改行の文字を除いたもの) と、位置が同じになる
43	  const parts = text.split(/(?<=\n)/);
44	  const header = scanHeader(parts.map((p) => p.replace(/\r?\n$/, "")));
45	  if (header.errors.length > 0) return { ok: false, errors: header.errors.map(formatOutlineError) };
46	  const line = `- ${INFO_LABELS[field]}: ${value}`;
47	  const existing = header.itemIndex[field];
48	  if (existing !== undefined) {
49	    const old = parts[existing] ?? "";
50	    parts[existing] = line + lineEnding(old);
51	    return { ok: true, text: parts.join("") };
52	  }
53	  // 誤りが無ければ必須の項目の行があるので、資料の情報の最後の行は必ずある
54	  const last = header.lastItemIndex;
55	  if (last === null) throw new Error("誤りの無い資料の情報に、項目の行が無い");
56	  const lastPart = parts[last] ?? "";
57	  const ending = lineEnding(lastPart);
58	  if (ending === "") {
59	    // 資料の情報の最後の行がファイルの最後の行で、改行が無い。改行を足してから行を足し、最後に改行が無い形を保つ
60	    parts[last] = lastPart + (text.includes("\r\n") ? "\r\n" : "\n");
61	    parts.splice(last + 1, 0, line);
62	  } else {
63	    parts.splice(last + 1, 0, line + ending);
64	  }
65	  return { ok: true, text: parts.join("") };
66	}
67	
68	/** 行の末尾の改行の文字 (\r\n・\n・無し)。 */
69	function lineEnding(part: string): string {
70	  if (part.endsWith("\r\n")) return "\r\n";
71	  if (part.endsWith("\n")) return "\n";
72	  return "";
73	}
