2	// 一致しなければ、build は PowerPoint のファイルを作らずに、この結果を一覧にして中断する。
3	
4	/** キーの突き合わせの結果。どの配列も、それぞれのキーが最初に現れた順序で並べる。 */
5	export interface KeyMismatch {
6	  /** 構成案にだけあるキー。 */
7	  outlineOnly: string[];
8	  /** 資料ごとのスクリプトにだけあるキー。 */
9	  deckOnly: string[];
10	  /** 資料ごとのスクリプトで、2 回以上図を作ったキー (1 回ずつ並べる)。構成案のキーの重複は、構成案を読むときに誤りにする。 */
11	  deckDuplicates: string[];
12	}
13	
14	/** 構成案のキーの配列と、資料ごとのスクリプトの図のキーの配列を突き合わせる。 */
15	export function matchKeys(outlineKeys: readonly string[], deckKeys: readonly string[]): KeyMismatch {
16	  const outline = new Set(outlineKeys);
17	  const deck = new Set(deckKeys);
18	  const seen = new Set<string>();
19	  const duplicates = new Set<string>();
20	  for (const k of deckKeys) {
21	    if (seen.has(k)) duplicates.add(k);
22	    seen.add(k);
23	  }
24	  return {
25	    outlineOnly: [...outline].filter((k) => !deck.has(k)),
26	    deckOnly: [...deck].filter((k) => !outline.has(k)),
27	    deckDuplicates: [...duplicates],
28	  };
29	}
30	
31	/** 突き合わせの結果に、不一致が 1 つでもあるか。 */
32	export function hasMismatch(m: KeyMismatch): boolean {
33	  return m.outlineOnly.length > 0 || m.deckOnly.length > 0 || m.deckDuplicates.length > 0;
34	}
